#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int rob(int* nums, int numsSize) {
    if (numsSize == 1) return nums[0];

    int prev2 = 0, prev1 = 0;
    int range1 = 0;
    for (int i = 0; i < numsSize - 1; ++i) {
        int current = prev1 > prev2 + nums[i] ? prev1 : prev2 + nums[i];
        prev2 = prev1;
        prev1 = current;
    }
    range1 = prev1;

    prev2 = 0;
    prev1 = 0;
    for (int i = 1; i < numsSize; ++i) {
        int current = prev1 > prev2 + nums[i] ? prev1 : prev2 + nums[i];
        prev2 = prev1;
        prev1 = current;
    }

    return range1 > prev1 ? range1 : prev1;
}

